function sumEvenGrandparent(root) {
  function dfs(node, parentVal, grandparentVal) {
    if (!node) {
      return 0;
    }
    const own = grandparentVal % 2 === 0 ? node.val : 0;
    const left = dfs(node.left, node.val, parentVal);
    const right = dfs(node.right, node.val, parentVal);
    return own + left + right;
  }

  // 1 is an odd stand-in for the missing parent and grandparent of the root.
  return dfs(root, 1, 1);
}

