    if (node.val % 2 === 0) {
      for (const child of [node.left, node.right]) {
        if (!child) continue;
        if (child.left) total += child.left.val;
        if (child.right) total += child.right.val;
      }
    }
    stack.push(node.left, node.right);
  }
  return total;
